<?php declare(strict_types=1);require_once dirname(__DIR__).'/_bootstrap.php';apiMethod('POST');apiCsrf();$uid=apiAuth();$in=apiInput();$nid=apiId($in['negotiation_id']??0);$msg=trim((string)($in['message']??''));if($msg==='')apiError('Message is required',422);$db=apiDb();$s=$db->prepare('SELECT n.id FROM negotiations n JOIN quotation_requests q ON q.id=n.quotation_request_id LEFT JOIN suppliers s ON s.id=q.supplier_id WHERE n.id=? AND (q.buyer_id=? OR s.user_id=?)');$s->execute([$nid,$uid,$uid]);if(!$s->fetch())apiError('Negotiation not found',404);$db->prepare('INSERT INTO negotiation_messages(negotiation_id,user_id,message) VALUES(?,?,?)')->execute([$nid,$uid,$msg]);apiResponse(['id'=>(int)$db->lastInsertId()],201);